const std = @import("std");

pub fn main() !void {
    const arr = [_]i32{ 10, 23, 42, 17, 55, 8, 99 };
    const target: i32 = 42;
    var found_index: ?usize = null;

    for (arr, 0..) |val, i| {
        if (val == target) {
            found_index = i;
            break;
        }
    }

    if (found_index) |idx| {
        std.debug.print("Found {} at index {}\n", .{target, idx});
    } else {
        std.debug.print("{} not found\n", .{target});
    }
}

